import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

batch_size = 16
dim = 16384

def get_inputs():
    x = torch.randn(batch_size, dim)
    return [x]

def get_init_inputs():
    return []

softmax_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void softmax_fwd_kernel(const float* __restrict__ x,
                                   float* __restrict__ y,
                                   const int B,
                                   const int D) {
    extern __shared__ float buf[];
    float* smax = buf;
    float* sexp = &buf[blockDim.x];

    int b = blockIdx.x;
    int tid = threadIdx.x;
    int offset = b * D;

    // 1) find maximum for this row
    float max_val = -FLT_MAX;
    for (int i = tid; i < D; i += blockDim.x) {
        float val = x[offset + i];
        max_val = fmaxf(val, max_val);
    }
    smax[tid] = max_val;
    __syncthreads();

    // reduce to get row max
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smax[tid] = fmaxf(smax[tid], smax[tid + stride]);
        }
        __syncthreads();
    }

    float rowMax = smax[0];
    __syncthreads();

    // 2) compute sum of exp
    float sum_val = 0.0f;
    for (int i = tid; i < D; i += blockDim.x) {
        sum_val += __expf(x[offset + i] - rowMax);
    }
    sexp[tid] = sum_val;
    __syncthreads();

    // reduce to get sum of exp
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sexp[tid] += sexp[tid + stride];
        }
        __syncthreads();
    }

    float rowSum = sexp[0];
    __syncthreads();

    // 3) write out final softmax
    for (int i = tid; i < D; i += blockDim.x) {
        y[offset + i] = __expf(x[offset + i] - rowMax) / rowSum;
    }
}

torch::Tensor softmax_cuda(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D for row-wise softmax.");
    int B = x.size(0);
    int D = x.size(1);

    auto out = torch::empty_like(x);

    const int blockSize = 256;
    dim3 grid(B);
    dim3 block(blockSize);
    size_t sharedMem = blockSize * sizeof(float) * 2;

    softmax_fwd_kernel<<<grid, block, sharedMem>>>(x.data_ptr<float>(),
                                                   out.data_ptr<float>(),
                                                   B,
                                                   D);
    return out;
}
"""

softmax_cpp_source = "torch::Tensor softmax_cuda(torch::Tensor x);"

softmax_ext = load_inline(
    name="softmax_ext",
    cpp_sources=softmax_cpp_source,
    cuda_sources=softmax_source,
    functions=["softmax_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softmax_ext = softmax_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softmax_ext.softmax_cuda(x)
